import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.util.StringTokenizer;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String line = br.readLine();if (line != null) {StringTokenizer st = new StringTokenizer(line);int x = Integer.parseInt(st.nextToken());int y = Integer.parseInt(st.nextToken());if (y > x) {out.println("YES");} else {out.println("NO");}}out.flush();out.close();}}